// For genuary2026, day 19, theme: "16x16". 

let turn = 0;
let num = 20;
let bg = 255;
let tbg = 255;

function setup() {
	createCanvas(windowWidth, windowHeight);
}

function draw() {
	bg = lerp(bg, tbg, 0.1)
	turn = lerp(turn,map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), width/12,11*width/12,-PI*2.5,PI*2.5, true),0.1)
	background(bg);
	translate(width / 2, height / 2);
	scale(height/628);
	for (let div = 1; div < 9; div += 1) {
		push();
		rotate(turn / 5*(div));
		drawGrid();
		pop();
	}
}

function drawGrid() {
	stroke(255-bg)
	num = lerp(num, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),height/12, 11*height/12, 16, 64, true), 0.01)
	for (let i = 0; i < floor(num); i++) {
		let x = -250 + (500/num) * i;
		strokeWeight(0.5 + 0.75*(i%2));
		line(x, -250, x, 250);
	}
}

function mousePressed(){
	tbg = 255-tbg;
}
